-- rowstile 0.1.0-dev: truncate_forgets_its_rows. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '65115f76104bf2d1', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '65115f76104bf2d1' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '65115f76104bf2d1' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '65115f76104bf2d1' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '082c0c51a15d7383' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '082c0c51a15d7383', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- trees built beside the ones in use (by the migration before) take their place
CREATE SCHEMA IF NOT EXISTS authz_keep;
ALTER TABLE authz_int."group__parent__tree__next" SET SCHEMA authz_keep;
ALTER TABLE authz_keep."group__parent__tree__next" RENAME TO "group__parent__tree";
ALTER INDEX authz_keep."group__parent__tree__next_pkey" RENAME TO "group__parent__tree_pkey";
ALTER INDEX authz_keep."group__parent__tree__next_ancestor_idx" RENAME TO "group__parent__tree_ancestor_idx";
ALTER TABLE authz_int."folder__parent__tree__next" SET SCHEMA authz_keep;
ALTER TABLE authz_keep."folder__parent__tree__next" RENAME TO "folder__parent__tree";
ALTER INDEX authz_keep."folder__parent__tree__next_pkey" RENAME TO "folder__parent__tree_pkey";
ALTER INDEX authz_keep."folder__parent__tree__next_ancestor_idx" RENAME TO "folder__parent__tree_ancestor_idx";

-- the triggers rebuilt trees made on tables their conditions read
DO $authz_dyn$
DECLARE r record;
BEGIN
  FOR r IN SELECT t.tgname, t.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger t
           WHERE t.tgname = ANY (ARRAY['authz_folder__parent__tree_dep', 'authz_group__parent__tree_dep']) LOOP
    EXECUTE format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_dyn$;

-- views that change stay where they are, emptied (the same columns, reading nothing) while what they
-- read is dropped and made again; they are defined again below. What the app built on one stays
DO $authz_stub$
DECLARE v text; cols text;
BEGIN
  FOREACH v IN ARRAY ARRAY['authz_int."folder__edit"', 'authz_int."folder__share"', 'authz_int."folder__view"', 'authz_int."group__manage"'] LOOP
    CONTINUE WHEN pg_catalog.to_regclass(v) IS NULL;
    SELECT (SELECT string_agg(format('NULL::%s%s AS %I', pg_catalog.format_type(a.atttypid, a.atttypmod),
        CASE WHEN a.attcollation <> 0 AND a.attcollation <> t.typcollation
             THEN format(' COLLATE %I.%I', cn.nspname, co.collname) ELSE '' END, a.attname), ', ' ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
      LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
      WHERE a.attrelid = pg_catalog.to_regclass(v) AND a.attnum > 0 AND NOT a.attisdropped) INTO cols;
    EXECUTE format('CREATE OR REPLACE VIEW %s AS SELECT %s WHERE false', v, cols);
  END LOOP;
END $authz_stub$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

