DELETE FROM authz_int.trees;
INSERT INTO authz_int.trees VALUES
  ('group__parent__tree', 'f4e017528cf2d18081c40e91310b33d6', ARRAY[to_regclass('"fm"."groups"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"fm"."groups"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid)),
  ('folder__parent__tree', '7cdf18bafd7ef4ae4c47d6dd53cf8d19', ARRAY[to_regclass('"fm"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"fm"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid));

-- group: each row with every ancestor it inherits from, through parent
CREATE TABLE authz_int."group__parent__tree" (descendant uuid NOT NULL, ancestor uuid NOT NULL,
  CONSTRAINT "group__parent__tree_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "group__parent__tree_ancestor_idx" ON authz_int."group__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('group', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."group__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."group__parent__tree";
    ALTER TABLE authz_keep."group__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('group__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."group__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."group__parent__tree_compute"(p_ids uuid[]) RETURNS TABLE (o_descendant uuid, o_ancestor uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "fm"."groups" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "fm"."groups" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "fm"."groups" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."group__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 9', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."group__parent__tree_shift"(p_ids uuid[], p_below uuid[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched uuid[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."group__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."group__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."groups" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."group__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."group__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."group__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."group__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."group__parent__tree_refresh"(p_ids uuid[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected uuid[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."group__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."group__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('group', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."group__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch uuid[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  DELETE FROM authz_int."group__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."groups") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."group__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."group__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."group__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch uuid[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."groups") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."group__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."group__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."group__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."group__parent__tree_check_loops"(p_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."group__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'group % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."group__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids uuid[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."group__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."group__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_group__parent__tree_ins" AFTER INSERT ON "fm"."groups"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_upd" AFTER UPDATE ON "fm"."groups"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_del" AFTER DELETE ON "fm"."groups"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_trunc" AFTER TRUNCATE ON "fm"."groups"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_truncate"();
COMMENT ON TRIGGER "authz_group__parent__tree_trunc" ON "fm"."groups" IS 'rowstile: for a TRUNCATE of the tables under its table too';

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'group__parent__tree') THEN
    PERFORM authz_int."group__parent__tree_rebuild"();
  END IF;
END $b$;

-- group__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'group__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'group__parent__tree') THEN
    RAISE EXCEPTION 'rowstile: group__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'group' AND '*' = ANY (c.object_ids)
                AND c.cause <> 'dependent'
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."group__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."group__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "fm"."groups" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::uuid FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'group' AND c.cause <> 'dependent'
        AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."group__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'group__parent__tree';
END $authz_catch_up$;

-- folder: each row with every ancestor it inherits from, through parent while {inherit}
CREATE TABLE authz_int."folder__parent__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  CONSTRAINT "folder__parent__tree_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "folder__parent__tree_ancestor_idx" ON authz_int."folder__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('folder', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."folder__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."folder__parent__tree";
    ALTER TABLE authz_keep."folder__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('folder__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."folder__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."folder__parent__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "fm"."folders" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "fm"."folders" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))
      AND EXISTS (SELECT 1 FROM "fm"."folders" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- the conditions on each row (and the type's where)
CREATE VIEW authz_int."folder__parent__tree_conds" AS
  SELECT r."id" AS id, ARRAY[coalesce((inherit), false)] AS v FROM "fm"."folders" r;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN
  CREATE TEMP TABLE authz_probe (LIKE "fm"."folders");
  BEGIN
    CREATE INDEX ON authz_probe ((coalesce((inherit), false)));
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION '%: a condition that limits inheritance must give the same answer for every user at any time (%) [AZ603]',
      'line 31', SQLERRM;
  END;
  DROP TABLE authz_probe;
  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."folder__parent__tree_links"'::regclass, 'authz_int."folder__parent__tree_conds"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 31', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE ((e._link = 0 AND coalesce((inherit), false))) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."folder__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."folder__parent__tree" u ON u.descendant = e._parent
    WHERE ((e._link = 0 AND coalesce((inherit), false))));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."folders" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."folder__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."folder__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."folder__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."folder__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."folder__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('folder', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."folder__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  DELETE FROM authz_int."folder__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."folder__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."folder__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."folder__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."folder__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."folder__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."folder__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."folder__parent__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."folder__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'folder % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
         OR (SELECT coalesce((inherit), false) FROM (SELECT n.*) r) IS DISTINCT FROM (SELECT coalesce((inherit), false) FROM (SELECT o.*) r)
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."folder__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder__parent__tree_ins" AFTER INSERT ON "fm"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_upd" AFTER UPDATE ON "fm"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_del" AFTER DELETE ON "fm"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_trunc" AFTER TRUNCATE ON "fm"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_truncate"();
COMMENT ON TRIGGER "authz_folder__parent__tree_trunc" ON "fm"."folders" IS 'rowstile: for a TRUNCATE of the tables under its table too';

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();
  END IF;
END $b$;

-- folder__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'folder__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    RAISE EXCEPTION 'rowstile: folder__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'folder' AND '*' = ANY (c.object_ids)
                AND c.cause <> 'dependent'
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."folder__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "fm"."folders" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::bigint FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'folder' AND c.cause <> 'dependent'
        AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."folder__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'folder__parent__tree';
END $authz_catch_up$;

-- shares on user rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE OR REPLACE FUNCTION authz_int."user__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_gone text[];
BEGIN
  IF TG_OP = 'TRUNCATE' AND NOT EXISTS (SELECT 1 FROM "fm"."users") THEN   -- the table is empty, and so are those under it
    DELETE FROM authz.shares WHERE object_type = 'user';
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id <> '*';      -- '*' (every one signed in) names no row
    DELETE FROM authz_int.row_marks WHERE type = 'user';
    PERFORM authz_int.requests_gone('user', NULL);
  ELSIF TG_OP = 'TRUNCATE' THEN   -- TRUNCATE ONLY, or of a table under it: some rows are still there. What named a
    -- row that is gone goes (the pending requests naming one were cancelled before, while it was there to tell)
    v_gone := ARRAY(SELECT g.id FROM (SELECT s.object_id FROM authz.shares s WHERE s.object_type = 'user'
                                      UNION SELECT s.subject_id FROM authz.shares s WHERE s.subject_type = 'user' AND s.subject_id <> '*'
                                      UNION SELECT m.id FROM authz_int.row_marks m WHERE m.type = 'user') g(id)
                    WHERE NOT EXISTS (SELECT 1 FROM "fm"."users" x WHERE x."id"::text = g.id));
    PERFORM authz_int.forget_marks('user', v_gone);
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id = ANY (v_gone);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id = ANY (v_gone);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
